"""Owned metric interpretation of original two authoritative reference images."""
import json,hashlib,collections,sys
from pathlib import Path
R=Path(__file__).resolve().parents[3];sys.path.insert(0,str(Path(__file__).parent));from preflight import audit

def write(scene,seed,rooms,doors,entrance,windows,levels=None):
 d=R/'data/venue_refs/floor_plans_v3'/scene;assert not (d/'floor_plan.json').exists();p={k:{} for k in ['rooms','doors','opens','interiors','windows','entrance']};m={};counts=collections.Counter()
 for key,sem,b in rooms:
  level=int(key[1]) if key.startswith('L') else 0;rid=f'{sem}_{level}/{counts[(sem,level)]}';counts[(sem,level)]+=1;x0,y0,x1,y1=b;pts=[(x0,y0),(x1,y0),(x1,y1),(x0,y1)];m[key]={'room_id':rid,'polygon_m':pts,'level':level,'floor_z_m':3.4*level};p['rooms'][rid]={'shape':f'shapely.Polygon({pts!r})'}
 for group,entries in [('doors',doors),('entrance',entrance),('windows',windows)]:
  for k,pts in entries:p[group][k]={'shape':f'shapely.LineString({pts!r})'}
 c={'scene_id':scene,'seed':seed,'revision':'plan_r0','source':'source.png','source_sha256':hashlib.sha256((d/'source.png').read_bytes()).hexdigest(),'dimension_authority':'Estimated from original image and adult native furniture dimensions; not surveyed','required_room_count':len(m),'required_semantic_counts':dict(collections.Counter(v['room_id'].split('_')[0] for v in m.values())),'minimum_door_width_m':.9,'minimum_room_area_m2':3,'entry_room':next(v['room_id'] for k,v in m.items() if 'hall' in k),'wall_height_m':3.2,'wall_thickness_m':.22,'levels':levels or [{'level':0,'z_m':0}],'source_uncertainties':['Original montage has no surveyed dimensions or city identity','Small wetroom labels ambiguous; functional requirements take precedence over duplicated text','Initial architectural proportions require image review and door clearance checks'],'required_views':['overview','living_context','terrace','master','kitchen'],'photorealism_accepted':False,'dataset_promoted':False}
 for n,x in [('floor_plan.json',p),('room_mapping.json',m),('scene_contract.json',c)]: (d/n).write_text(json.dumps(x,indent=2)+'\n')
 if not levels:
  # semantic tokens must use full semantic prefix, not split at hyphens.
  c['required_semantic_counts']=dict(collections.Counter(v['room_id'].split('_0/')[0] for v in m.values()));(d/'scene_contract.json').write_text(json.dumps(c,indent=2)+'\n');a=audit(d);(d/'preflight_layout.json').write_text(json.dumps(a,indent=2));print(scene,a['status'],a.get('failures'))
 else:(d/'preflight_layout.json').write_text(json.dumps({'status':'custom_multilevel_authoring_required','reason':'Single-level native validator cannot certify overlapping XY rooms on different levels','levels':levels,'void_m':[5,5,11,11],'stair':{'width_m':1.25,'rise_m':.17,'tread_m':.30,'risers':20,'floor_height_m':3.4}},indent=2))

